import * as crypto from "crypto";
import { PutItemCommand } from "@aws-sdk/client-dynamodb";
import { InvokeCommand, LambdaClient } from "@aws-sdk/client-lambda";
import { PutObjectCommand } from "@aws-sdk/client-s3";
import { createLogger } from 'admin-auth';

const logger = createLogger('importuserslist-post');

const headers = {
  "Access-Control-Allow-Headers":
    "Content-Type,Authorization,X-Api-Key,Content-Range,X-Requested-With",
  "Access-Control-Allow-Credentials": true,
  "Content-Type": "application/json",
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "OPTIONS,GET,POST",
};

const lambda = new LambdaClient({ region: process.env.AWS_REGION });

const genImportUsersJob = async (
  userPoolId,
  admin,
  notify,
  totalusernumber,
  dynamodb,
  importJobTable,
) => {
  logger.info("generating user import job id for userpool id:", userPoolId);

  const jobid = crypto.randomUUID();
  const timestamp = Date.now();

  const params = {
    Item: {
      jobid: {
        S: jobid,
      },
      notify: {
        BOOL: notify,
      },
      jobstatus: {
        S: "PENDING",
      },
      totalusers: {
        N: `${totalusernumber}`,
      },
      userpoolid: {
        S: userPoolId,
      },
      createdby: {
        S: admin ? admin : '',
      },
      timestamp: {
        N: `${timestamp}`,
      },
      ttl: {
        N: `${parseInt(timestamp / 1000 + 3600 * 24 * 7)}`, //7 days
      },
    },
    ReturnConsumedCapacity: "TOTAL",
    TableName: importJobTable,
  };

  console.log("params:", { Bucket: params.Bucket, Key: params.Key })
  const putItemCommand = new PutItemCommand(params);
  const results = await dynamodb.send(putItemCommand);
  logger.info("user import job id creation result:", results);

  return jobid;
};

// Import bounds (amfa-442 A5 "Import payload unbounded"): the worker fans
// every entry out to AdminCreateUser / AdminAddUserToGroup, whose quotas are
// per AWS account, so one oversized body throttles every other tenant.
export const MAX_IMPORT_USERS = 10000;
export const MAX_IMPORT_BYTES = 5 * 1024 * 1024;
export const MAX_GROUPS_PER_USER = 20;

/**
 * First reason the import body is unusable, or null when it is within bounds.
 * `email` must be a string (the worker derives the Cognito username from it);
 * any `groups` key (the worker matches it case-insensitively) must be an
 * array of at most MAX_GROUPS_PER_USER strings.
 */
export const validateImportPayload = (data) => {
  const userData = data?.userData;
  if (!Array.isArray(userData)) return "userData: must be an array";
  if (userData.length > MAX_IMPORT_USERS) return `userData: at most ${MAX_IMPORT_USERS} entries`;
  if (Buffer.byteLength(JSON.stringify(userData)) > MAX_IMPORT_BYTES) return "userData: serialized size exceeds 5 MB";
  for (let i = 0; i < userData.length; i++) {
    const user = userData[i];
    if (!user || typeof user !== "object" || Array.isArray(user)) return `userData[${i}]: must be an object`;
    if (typeof user.email !== "string" || user.email === "") return `userData[${i}].email: must be a non-empty string`;
    // The worker lower-cases keys and concatenates every "groups" variant, so
    // the bound applies to all of them together.
    const groupKeys = Object.keys(user).filter((k) => k.toLowerCase() === "groups");
    if (groupKeys.length > 1) return `userData[${i}]: duplicate groups key (${groupKeys.join(", ")})`;
    for (const key of groupKeys) {
      const groups = user[key];
      if (!Array.isArray(groups) || groups.length > MAX_GROUPS_PER_USER || groups.some((g) => typeof g !== "string")) {
        return `userData[${i}].${key}: must be an array of at most ${MAX_GROUPS_PER_USER} strings`;
      }
    }
  }
  return null;
};

export const postResData = async (data, userpoolId, tenantId, dynamodbISP, s3, importJobTable) => {
  const invalid = validateImportPayload(data);
  if (invalid) {
    return {
      statusCode: 400,
      headers,
      body: JSON.stringify({ type: "exception", message: invalid }),
    };
  }

  try {
    const jobid = await genImportUsersJob(
      userpoolId,
      data.admin,
      data.notify,
      data.userData.length,
      dynamodbISP,
      importJobTable,
    );

    // start worker lambda with event type
    logger.info("start worker lambda with event type");

    // Keys are prefixed with the authorized tenant: the bucket is shared by
    // all tenants (amfa-442 A5 "Import job result objects").
    const params = {
      Bucket: process.env.IMPORTUSERS_BUCKET,
      Key: `jobs/${tenantId}/${jobid}`,
      Body: JSON.stringify(data.userData),
    }

    const res = await s3.send(new PutObjectCommand(params))
    logger.info("upload jobdata to s3:", { httpStatusCode: res?.$metadata?.httpStatusCode })

    const command = new InvokeCommand({
      FunctionName: process.env.IMPORTUSERS_WORKER_LAMBDA,
      InvocationType: "Event",
      Payload: JSON.stringify({
        jobid,
        notify: data.notify,
        userpoolId,
        tenantId,
        admin: data.admin,
        tableName: importJobTable,
      }),
    });

    const response = await lambda.send(command);
    logger.info("start worker lambda response:", { StatusCode: response.StatusCode });

    return {
      statusCode: 200,
      headers,
      body: JSON.stringify({ message: "Import job started.", JobId: jobid }),
    };
  } catch (e) {
    logger.info("Catch an error: ", e);
    return {
      statusCode: 500,
      headers,
      body: JSON.stringify({ message: "Failed to start import job." }),
    };
  }
};

export default postResData;
